model.css:
.card {
  margin: 0;
  padding: 0;
  background: #ffffff;
  color: #111111;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Inter", "Segoe UI", Arial, sans-serif;
  font-size: 20px;
  line-height: 1.45;
  text-align: left;
}

.codex-shell {
  box-sizing: border-box;
  width: min(100%, 1180px);
  min-height: 72vh;
  margin: 0 auto;
  padding: 42px 64px 96px;
}

.codex-question {
  font-size: 23px;
  font-weight: 400;
  line-height: 1.35;
  letter-spacing: 0;
  margin: 0 0 72px;
}

.codex-tags {
  min-height: 34px;
  margin: 0 0 16px;
}

.codex-tag-pill {
  display: inline-block;
  max-width: 100%;
  border: 1px solid #b7b7b7;
  border-radius: 7px;
  background: #eeeeee;
  color: #111111;
  padding: 6px 12px;
  font-size: 20px;
  font-weight: 700;
  line-height: 1.15;
  overflow-wrap: anywhere;
}

.codex-answer-wrap {
  margin-top: 92px;
}

.codex-answer {
  border-left: 3px solid #e8e8e8;
  padding-left: 24px;
  font-size: 22px;
  line-height: 1.45;
}

.codex-answer p:first-child,
.codex-answer div:first-child {
  margin-top: 0;
}

.codex-answer img {
  max-width: min(100%, 420px);
  height: auto;
  border-radius: 6px;
}

.codex-divider,
hr#answer {
  display: none;
}

.replay-button,
.soundLink {
  vertical-align: middle;
}

@media (max-width: 720px) {
  .codex-shell {
    padding: 28px 24px 72px;
  }

  .codex-question {
    font-size: 21px;
    margin-bottom: 48px;
  }

  .codex-answer {
    font-size: 20px;
    padding-left: 18px;
  }
}
